package app.stak.nativeapp.data

import com.google.gson.*
import kotlinx.coroutines.runBlocking
import org.junit.Assert.*
import org.junit.Test

/** Golden responses generated by the real Python rule_from_dict/rule_to_dict,
 * not an echo stub: catches semantic differences in production's response. */
class WatcherCanonicalContractTest {
    private val cases=JsonParser.parseString(javaClass.getResource("/watcher-canonical-rules.json")!!.readText()).asJsonArray
    private fun local(request:JsonObject):WatchRuleModel {
        val ids=request.getAsJsonObject("series")
        return WatchRuleModel(ruleId=request.get("ruleId").asString,seriesImdb=ids.get("imdb").asString,
            seriesTmdb=ids.get("tmdb").asString,seriesTvdb=ids.get("tvdb").asString,seriesName=ids.get("name").asString,
            enabled=true,createdOn=request.get("createdOn").asString,watchedSeasons=listOf(2,1),
            resolutionMode=request.get("resolutionMode").asString,resolutionWaitHours=request.get("resolutionWaitHours").asInt,
            releaseTypes=listOf("WEB-DL","Remux"),state=WatchRuleModel.STATE_SAVED_LOCAL,pendingAction="save")
    }
    private class Memory(rule:WatchRuleModel):WatchRulePersistence{
        var doc=WatcherDocument(WatcherDocument().version,WatcherConnection("https://watch.example/","synthetic-token-123456789",true),listOf(rule))
        override fun read()=doc
        override fun update(change:(WatcherDocument)->WatcherDocument):WatcherDocument{doc=change(doc);return doc}
    }
    private fun factory(response:JsonObject,posts:MutableList<JsonObject>):(WatcherConnection)->WatcherClient={connection->
        WatcherClient(connection,object:HttpWatcherTransport(){
            override fun call(connection:WatcherConnection,path:String,body:JsonObject?,method:String):JsonObject {
                if(method=="POST"){posts+=body!!;return JsonObject().apply{add("rule",response);add("issues",JsonArray())}}
                if(path.startsWith("v1/episodes"))return JsonObject().apply{add("items",JsonArray())}
                return response.deepCopy()
            }
        })
    }

    @Test fun productionCanonicalResponsesMatchAllResolutionModesAndNumericIds(){
        cases.forEach{entry->val c=entry.asJsonObject
            assertTrue("Expected ${WatcherCodec.payloadFor(local(c.getAsJsonObject("request")),true)} vs ${c.getAsJsonObject("response")}",watchRuleMatches(local(c.getAsJsonObject("request")),c.getAsJsonObject("response")))
        }
    }

    @Test fun existingStrict4kPendingRuleRecoversByReadingWithoutAnyResave()=runBlocking{
        val c=cases[0].asJsonObject;val p=Memory(local(c.getAsJsonObject("request")));val posts=mutableListOf<JsonObject>()
        WatchRules.refresh(p,factory(c.getAsJsonObject("response"),posts))
        assertEquals("Active",autoAddMode(p.doc.rules.single()));assertNull(p.doc.rules.single().pendingAction)
        assertTrue("Recovery must not cause acquisition or another rule write",posts.isEmpty())
    }

    @Test fun saveThenRefreshDoesNotFlipActiveBackToPending()=runBlocking{
        cases.forEach{entry->val c=entry.asJsonObject;val p=Memory(local(c.getAsJsonObject("request")));val posts=mutableListOf<JsonObject>()
            val f=factory(c.getAsJsonObject("response"),posts)
            WatchRules.saveRule(p.doc.rules.single(),true,p,f)
            WatchRules.refresh(p,f)
            assertEquals("Active",autoAddMode(p.doc.rules.single()))
            assertEquals(1,posts.size)
            assertEquals(c.getAsJsonObject("response").get("resolutionWaitHours").asInt,posts.single().get("resolutionWaitHours").asInt)
        }
    }

    @Test fun realQualityDifferencesStillStayPending(){
        val c=cases[0].asJsonObject;val r=local(c.getAsJsonObject("request"));val remote=c.getAsJsonObject("response").deepCopy()
        remote.addProperty("hdrMode","mandatory");assertFalse(watchRuleMatches(r,remote))
    }

    @Test fun preferredWaitDifferencesAreNotIgnored(){
        val c=cases[2].asJsonObject;val r=local(c.getAsJsonObject("request"));val remote=c.getAsJsonObject("response").deepCopy()
        remote.addProperty("resolutionWaitHours",72);assertFalse(watchRuleMatches(r,remote))
    }
}
